using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.ConceptDynamics.Coding.PositiveRecoding;

internal sealed class ActualRankedPermutationRelabelDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Ranked permutation factors as actual graph relabelings.",
        H("Ranked permutation factors as actual graph relabelings"),
        Blocks(
            Paragraph(Text("Construct the permutation factor P from e : Fin n ≃ Fin m and take arbitrary nonnegative q : CountMat m n. The distinguished P half-edge has number zero and is unique. rankedForward joins the old Q half-edge to the P edge at the old target; rankedInverse recovers the preceding P half-edge. The inverse equations use the existing ranked split/join operations, rather than just cardinalities. Their endpoint laws produce rankedRelabel, and ranked_coordinate identifies its action with elementaryHomeomorph on every integer coordinate.")),
            Paragraph(Text("P_mul_Q and Q_mul_P specialize Q e A to recover A and its vertex reindexing. ranked_residue additionally retains hA : P e * q = A, hB : q * P e = B and hv : r.vertex = e; it compares reduced gyration only for d with NeZero d and hd : 3 ∣ d. It does not assert that a graph relabeling has zero integral or unreduced phase. Finite dimensions, including zero, and empty q fibers remain in scope.")),
            Paragraph(Text("These constructions and identities are repository-derived. Their provenance does not assert literature novelty.")),
            Describe.Lean(DescribeId.Create("positive-recoding-actualrankedpermutationrelabel-ranked-relabel"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRankedPermutationRelabel.rankedRelabel"), H("rankedRelabel"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The actual ranked elementary recoding is a graph relabel in this case. Both inverses have just been proved using split/join, not cardinality."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("positive-recoding-actualrankedpermutationrelabel-ranked-coordinate"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRankedPermutationRelabel.ranked_coordinate"), H("ranked_coordinate"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("On every integer coordinate, the ranked elementary homeomorphism agrees with the edge map of rankedRelabel. This identifies the path action, including the original parallel-edge numbers."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("positive-recoding-actualrankedpermutationrelabel-ranked-residue"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRankedPermutationRelabel.ranked_residue"), H("ranked_residue"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("For nonzero periods divisible by three, the factor equations for P and q and the prescribed vertex bijection compare the actual relabel gyration with the ranked elementary gyration after reduction to ZMod 3."))), DescribeRole.Theorem),
            Describe.Remark(DescribeId.Create("positive-recoding-actualrankedpermutationrelabel-p"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRankedPermutationRelabel.P"), H("P"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The permutation matrix records one numbered edge from each vertex to its image under e. It is the forward factor in the ranked relabel construction.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-actualrankedpermutationrelabel-q"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRankedPermutationRelabel.Q"), H("Q"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Reindex the rows of A by the inverse vertex bijection. This supplies the complementary nonnegative factor without changing edge multiplicities.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-actualrankedpermutationrelabel-p-mul-q"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRankedPermutationRelabel.P_mul_Q"), H("P_mul_Q"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Multiplying the permutation factor by its complementary factor recovers A. This is the old-graph endpoint of the elementary recoding.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-actualrankedpermutationrelabel-q-mul-p"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRankedPermutationRelabel.Q_mul_P"), H("Q_mul_P"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The reverse product is A reindexed in both vertex coordinates. This identifies the new graph of the same elementary recoding.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-actualrankedpermutationrelabel-p-edge"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRankedPermutationRelabel.pEdge"), H("pEdge"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The distinguished P edge at i exists without any Q-edge existence assumption. In dimension zero this is a function out of the empty type.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-actualrankedpermutationrelabel-p-target"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRankedPermutationRelabel.p_target"), H("p_target"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Every permutation edge ends at the image of its source. The endpoint constraint is used when joining the two ranked half-edges.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-actualrankedpermutationrelabel-p-unique"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRankedPermutationRelabel.p_unique"), H("p_unique"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The edge from a given source in the permutation factor is unique, including its number. This lets the inverse construction recover the original edge.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-actualrankedpermutationrelabel-ranked-forward"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRankedPermutationRelabel.rankedForward"), H("rankedForward"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Shift the actual Q half-edge left and append the unique P edge at the OLD target. This defines an edge map, before any path is considered.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-actualrankedpermutationrelabel-ranked-inverse"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRankedPermutationRelabel.rankedInverse"), H("rankedInverse"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Split the target edge, retain its Q half, and insert the unique P half at the recovered old source. This reverses rankedForward using the original split/join operations.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-actualrankedpermutationrelabel-ranked-left"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRankedPermutationRelabel.ranked_left"), H("ranked_left"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Splitting after the forward join recovers the original two halves. Uniqueness of the permutation half proves the left inverse on actual numbered edges.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-actualrankedpermutationrelabel-ranked-right"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRankedPermutationRelabel.ranked_right"), H("ranked_right"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The complementary split/join cancellation proves the right inverse on every target edge, with no nonempty-fiber premise.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-actualrankedpermutationrelabel-ranked-timed"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRankedPermutationRelabel.ranked_timed"), H("ranked_timed"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The coordinate identity identifies the two time-equivariant path equivalences. Their equality transfers the existing elementary gyration formula to the ranked relabel.")))))));
}
